import React from 'react';
import './Header.css'; // Import CSS file for styling
import avatar from "./avatar.png";
import { Box, Grid, Typography } from '@mui/material';
import { useUser } from '../../Context/userContext';
import RatingBox from '../../Component/RatingBox';
const Header = () => {
    const { user } = useUser();
    return (

    <Box
      className="header"
      sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 2,
        backgroundColor: '#e0f7f4', // สีพื้นหลังอ่อน ๆ
      }}
    >
      {/* ฝั่งซ้าย: Avatar */}
      <Box sx={{ marginRight: 3 }}>
        <Avatar
          src={avatar}
          alt="avatar"
          sx={{ width: 100, height: 100 }}
        />
      </Box>

      {/* ฝั่งขวา: ข้อมูลสมาชิก */}
      <Stack spacing={1} sx={{ textAlign: 'left' }}>
        <RatingBox value={5} title="คะแนน" />
        <Typography variant="body1">รหัสสมาชิก: 123456</Typography>
        <Typography variant="h6">ชื่อสมาชิก: Akkdach Narach</Typography>
      </Stack>
    </Box>

    );
};

export default Header;
